#include <iostream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> prob(n);
    for (int i = 0; i < n; ++i) {
        cin >> prob[i];
    }

    vector<double> ans(n, 0.0);
    vector<double> dp(1 << n, 0.0);
    vector<double> sum(1 << n, 0.0);

    auto count_bits = [](int x) {
        int count = 0;
        while (x) {
            count += x & 1;
            x >>= 1;
        }
        return count;
    };

    for (int mask = 0; mask < (1 << n); ++mask) {
        double s = 0.0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i))
                s += prob[i];
        }
        sum[mask] = s;
    }

    dp[0] = 1.0;
    int flag = 0;

    for (int mask = 0; mask < (1 << n); ++mask) {
        int qb = count_bits(mask);
        if (qb > k) continue;
        if (dp[mask] < 1e-100) continue;
        if (qb == k) flag = 1;
        double rem_sum = 1.0 - sum[mask];
        if (rem_sum < 1e-6) continue;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            double chance_move = dp[mask] * prob[i] / rem_sum;
            dp[mask | (1 << i)] += chance_move;
        }
    }

    if (flag == 0) {
        for (int i = 0; i < n; ++i) {
            ans[i] = (prob[i] < 1e-6) ? 0.0 : 1.0;
        }
    } else {
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (count_bits(mask) == k) {
                for (int i = 0; i < n; ++i) {
                    if (mask & (1 << i))
                        ans[i] += dp[mask];
                }
            }
        }
    }

    cout << fixed << setprecision(12);
    for (int i = 0; i < n; ++i) {
        if (i) cout << " ";
        cout << ans[i];
    }
    cout << "\n";

    return 0;
}
